#!/usr/bin/env bash\nset -euo pipefail\n\n# Create a temporary event payload\nEVENT_JSON=$(cat <<'EOF'\n{\n  "pull_request": {\n    "title": "Bug: fix crash on startup"\n  }\n}\nEOF\n)\n\nTMP_EVENT=$(mktemp)\necho "$EVENT_JSON" > "$TMP_EVENT"\nexport GITHUB_EVENT_PATH="$TMP_EVENT"\nexport GITHUB_TOKEN="dummy-token"\n\n# Capture output\nOUTPUT=$(bash "$(dirname \"$0\")/../src/labeler.sh")\n\n# Expected substrings\nif [[ "$OUTPUT" != *"Would add labels: bug"* ]]; then\n  echo "Test failed: expected label 'bug' not found"\n  exit 1\nfi\n\nif [[ "$OUTPUT" != *"Would post comment"* ]]; then\n  echo "Test failed: expected comment output"\n  exit 1\nfi\n\necho "All tests passed."\n
